import{_ as i,c as o,o as e,ah as t}from"./chunks/framework.BkHe6ehV.js";const g=JSON.parse('{"title":"Claude 系列","description":"","frontmatter":{"title":"Claude 系列","date":"2025-12-06 11:55:44","create":"2025-12-06 11:55:44","categories":["claude"],"tags":["claude3","claude4","claude 4.5"],"readingStats":{"words":4586,"minutes":14,"images":2}},"headers":[],"relativePath":"posts/llm/industry/mainllm/09-claude-series.md","filePath":"posts/llm/industry/mainllm/09-claude-series.md","lastUpdated":1785944275000}'),a={name:"posts/llm/industry/mainllm/09-claude-series.md"};function s(n,l,r,c,d,u){return e(),o("div",null,l[0]||(l[0]=[t('<h2 id="变化点" tabindex="-1">变化点 <a class="header-anchor" href="#变化点" aria-label="Permalink to &quot;变化点&quot;">​</a></h2><div class="custom-block tip"><div class="custom-block-title">2026</div><p><strong>2026.09 · <a href="#_2609-fable-5-1-mythos-5-1-同一基座、领域防护与路由">Fable 5.1 / Mythos 5.1</a></strong></p><ul><li>共享模型基座，以领域防护、访问策略和路由区分部署。</li><li>兼顾复杂任务能力、主动核验与实际使用效率。</li></ul><p><strong>2026.07 · <a href="#_2607-claude-opus-5-主动验证、effort-与执行效率">Claude Opus 5</a></strong></p><ul><li>强化主动检查与结果验证，减少任务完成后的遗漏。</li><li>结合 effort 控制优化质量与执行成本。</li></ul><p><strong>2026.02 · <a href="#_2602-claude-opus-4-6-adaptive-thinking、compaction">Claude Opus 4.6</a></strong></p><ul><li>引入 Adaptive Thinking，按任务需要调整推理投入。</li><li>结合 Compaction 与长上下文，支撑更长的 Agent 任务。</li></ul></div><div class="custom-block info"><div class="custom-block-title">2025</div><p><strong>2025.09 · <a href="#_2509-claude-sonnet-4-5-context-editing、memory、长程-agent">Claude Sonnet 4.5</a></strong></p><ul><li>引入 Context Editing 与外部 Memory，管理长任务的上下文。</li><li>强化长程 Coding Agent 与连续工具执行。</li></ul><p><strong>2025.05 · <a href="#_2505-claude-opus-4-sonnet-4-推理工具交替与奖励投机">Claude Opus 4 / Sonnet 4</a></strong></p><ul><li>在推理过程中交替使用工具，提高复杂代码任务的持续执行能力。</li></ul><p><strong>2025.02 · <a href="#_2502-claude-3-7-sonnet-hybrid-reasoning、claude-code">Claude 3.7 Sonnet</a></strong></p><ul><li>将普通回答与 Extended Thinking 统一为 Hybrid Reasoning。</li><li>配合 Claude Code，扩展终端中的代码交互。</li></ul></div><div class="custom-block note"><div class="custom-block-title">2024 及以前</div><p><strong>2024.10 · <a href="#_2410-claude-3-5-sonnet更新-computer-use、屏幕到动作">Claude 3.5 Sonnet 更新</a></strong></p><ul><li>引入 Computer Use，由截图理解生成鼠标与键盘动作。</li><li>将工具交互扩展到图形界面。</li></ul><p><strong>2024.06 · <a href="#_2406-claude-3-5-sonnet-代码库交互、视觉推理">Claude 3.5 Sonnet</a></strong></p><ul><li>强化代码库修改与视觉推理，提高多步代码交互能力。</li></ul><p><strong>2024.03 · <a href="#_2403-claude-3-opus-sonnet-haiku、视觉与长上下文">Claude 3</a></strong></p><ul><li>引入视觉输入与长上下文，形成 Opus / Sonnet / Haiku 分层。</li></ul><p><strong>2022.12 · <a href="#_2212-constitutional-ai-自我修订与-ai-偏好">Constitutional AI（对齐方法）</a></strong></p><ul><li>用原则指导模型自我批评和修订，构建 SFT 数据。</li><li>再用 AI 偏好进行 RL，减少对人工有害内容标注的依赖。</li></ul></div><h2 id="_2609-fable-5-1-mythos-5-1-同一基座、领域防护与路由" tabindex="-1">(2609) Fable 5.1 / Mythos 5.1 (同一基座、领域防护与路由) <a class="header-anchor" href="#_2609-fable-5-1-mythos-5-1-同一基座、领域防护与路由" aria-label="Permalink to &quot;(2609) Fable 5.1 / Mythos 5.1 (同一基座、领域防护与路由)&quot;">​</a></h2><div class="custom-block tip"><div class="custom-block-title">Fable 5.1 / Mythos 5.1：同一基座与不同防护</div><p><strong>来源与版本关系</strong></p><ul><li><a href="https://www.anthropic.com/claude/mythos" target="_blank" rel="noreferrer">官方模型页</a>。</li><li>两者共享底层模型；Mythos 面向审核后的专业机构，Fable 增加广泛服务所需防护。</li></ul><p><strong>请求处理</strong></p><ul><li>Fable 5.1 支持源代码漏洞识别，对部分高风险请求限制或回退。</li><li>生物、化学等触发条件的请求路由到 Opus，继续提供可用响应。</li><li>基模能力相同，生产防护与模型路由仍会影响系统最终完成的任务。</li></ul></div><div class="custom-block important"><div class="custom-block-title">公开表现</div><p><strong>领域能力与正常请求</strong></p><ul><li>官方报告网络安全与生物研究能力提升，Fable 扩大源代码漏洞识别的可用范围。</li><li>相对 Fable 5，正常生物请求的防护干预减少约 <code>85%</code>，日常任务较少被误拦截。</li><li>系统评测中 Fable 使用生产防护，Mythos 对照用于观察防护影响。</li></ul></div><h2 id="_2607-claude-opus-5-主动验证、effort-与执行效率" tabindex="-1">(2607) Claude Opus 5 (主动验证、Effort 与执行效率) <a class="header-anchor" href="#_2607-claude-opus-5-主动验证、effort-与执行效率" aria-label="Permalink to &quot;(2607) Claude Opus 5 (主动验证、Effort 与执行效率)&quot;">​</a></h2><div class="custom-block tip"><div class="custom-block-title">Claude Opus 5：主动验证与推理投入</div><p><strong>来源与问题</strong></p><ul><li><a href="https://www.anthropic.com/news/claude-opus-5" target="_blank" rel="noreferrer">Introducing Claude Opus 5</a>。</li><li>复杂工程任务容易只修表面症状，增加推理预算又会提高单任务成本。</li></ul><p><strong>主动验证</strong></p><ul><li>定位根因、检查实际产物，再针对遗漏和边界情况修改。</li><li>官方案例中，缺少实时数据时主动构建测试 harness，验证解析行为。</li><li>Effort 调整推理投入，按完整任务质量、延迟与成本选择运行配置。</li></ul></div><div class="custom-block important"><div class="custom-block-title">公开表现与运行条件</div><p><strong>Frontier-Bench v0.1</strong></p><ul><li>mini-SWE-agent、GKE，每题 <code>5</code> 次尝试取平均奖励；安全拒绝可回退 Opus 4.8。</li><li>表现超过 Opus 4.8 的 <code>2 倍</code>，同时降低单任务成本。</li></ul><p><strong>CursorBench 3.2</strong></p><ul><li>跨 Effort 比较质量与成本，最高 Effort 与 Fable 5 峰值差距在 <code>0.5%</code> 内，成本约一半。</li><li>收益体现在较低成本下完成更多有效工作，不能仅以输出速度衡量效率。</li></ul></div><h2 id="_2602-claude-opus-4-6-adaptive-thinking、compaction" tabindex="-1">(2602) Claude Opus 4.6 (Adaptive Thinking、Compaction) <a class="header-anchor" href="#_2602-claude-opus-4-6-adaptive-thinking、compaction" aria-label="Permalink to &quot;(2602) Claude Opus 4.6 (Adaptive Thinking、Compaction)&quot;">​</a></h2><div class="custom-block tip"><div class="custom-block-title">Claude Opus 4.6：自适应推理与上下文压缩</div><p><strong>来源与配置</strong></p><ul><li><a href="https://www.anthropic.com/news/claude-opus-4-6" target="_blank" rel="noreferrer">Introducing Claude Opus 4.6</a>。</li><li>发布时提供 <code>1M</code> 上下文 Beta、最大 <code>128K</code> 输出，面向大代码库与长任务。</li></ul><p><strong>Adaptive Thinking</strong></p><ul><li>模型按任务决定思考深度，Effort 提供 <code>low / medium / high / max</code>，控制推理投入。</li></ul><p><strong>Context Compaction</strong></p><ul><li>会话接近配置阈值时，将较早历史替换为摘要，再继续任务。</li><li>摘要传递已确认信息和任务状态，作用于输入历史，不更新模型参数。</li></ul></div><div class="custom-block important"><div class="custom-block-title">公开表现</div><p><strong>长上下文检索</strong></p><ul><li>MRCR v2，<code>8-needle / 1M</code>：Sonnet 4.5 <code>18.5 → Opus 4.6 76.0</code>。</li><li>指定信息的定位与取回明显改善，长窗口具备更高的实际利用率。</li></ul><p><strong>专业知识工作</strong></p><ul><li>GDPval-AA 比 Opus 4.5 高约 <code>190 Elo</code>，收益扩展到专业工作产物。</li><li>长任务仍需让检索、深度推理和摘要状态相互配合。</li></ul></div><h2 id="_2509-claude-sonnet-4-5-context-editing、memory、长程-agent" tabindex="-1">(2509) Claude Sonnet 4.5 (Context Editing、Memory、长程 Agent) <a class="header-anchor" href="#_2509-claude-sonnet-4-5-context-editing、memory、长程-agent" aria-label="Permalink to &quot;(2509) Claude Sonnet 4.5 (Context Editing、Memory、长程 Agent)&quot;">​</a></h2><div class="custom-block tip"><div class="custom-block-title">Claude Sonnet 4.5：上下文清理与跨会话记忆</div><p><strong>来源与问题</strong></p><ul><li><a href="https://www.anthropic.com/news/claude-sonnet-4-5" target="_blank" rel="noreferrer">官方发布</a>、<a href="https://claude.com/blog/context-management" target="_blank" rel="noreferrer">上下文管理</a>。</li><li>工具结果持续挤占窗口，跨会话后又容易丢失进展，需要分别管理当前历史与外部状态。</li></ul><p><strong>Context Editing</strong></p><ul><li>接近阈值时移除旧工具调用与结果，保留近期交互和任务连贯性。</li></ul><p><strong>Memory Tool</strong></p><ul><li>模型操作客户端文件，保存结论、进展和待办，后续会话重新读取。</li><li>这是外部记忆管理，不是通过更新权重学习历史。</li></ul></div><div class="custom-block important"><div class="custom-block-title">仓库修复与多候选选择</div><p><strong>生成与筛选</strong></p><ul><li>并行生成候选补丁，先过滤破坏仓库可见回归测试的候选。</li><li>内部评分模型对剩余补丁排序，选择最终提交，不使用隐藏测试选优。</li></ul><p><strong>SWE-bench Verified</strong></p><ul><li>完整 <code>500</code> 题，Bash + 字符串替换编辑器，<code>10</code> 次运行平均。</li><li>主设置 <code>200K thinking budget</code>，Prompt 鼓励工具使用和先写测试。</li><li>单次求解 <code>77.2</code>，多候选选优 <code>82.0</code>，额外推理期搜索仍能提高修复率。</li></ul></div><div class="custom-block note"><div class="custom-block-title">上下文消融与 GUI 表现</div><p><strong>内部 Agent Search</strong></p><ul><li>Context Editing 单独提高 <code>29%</code>，与 Memory 联合提高 <code>39%</code>。</li><li><code>100</code> 轮搜索的 tokens 消耗降低 <code>84%</code>，清理旧输出减少窗口压力。</li><li>当前窗口清理与跨会话记忆相互补充，分别处理历史堆积和会话间信息丢失。</li></ul><p><strong>电脑操作</strong></p><ul><li>OSWorld-Verified <code>61.4</code>；最多 <code>100</code> 步，<code>4</code> 次运行平均。</li></ul></div><h2 id="_2505-claude-opus-4-sonnet-4-推理工具交替与奖励投机" tabindex="-1">(2505) Claude Opus 4 / Sonnet 4 (推理工具交替与奖励投机) <a class="header-anchor" href="#_2505-claude-opus-4-sonnet-4-推理工具交替与奖励投机" aria-label="Permalink to &quot;(2505) Claude Opus 4 / Sonnet 4 (推理工具交替与奖励投机)&quot;">​</a></h2><div class="custom-block tip"><div class="custom-block-title">Claude 4：训练与技术定位</div><p><strong>来源与任务</strong></p><ul><li><a href="https://www-cdn.anthropic.com/07b2a3f9902ee19fe39a36ca638e5ae987bc64dd.pdf" target="_blank" rel="noreferrer">System Card: Claude Opus 4 &amp; Claude Sonnet 4</a>、<a href="https://www.anthropic.com/news/claude-4" target="_blank" rel="noreferrer">官方发布</a>。</li><li>长程 Coding Agent 需要持续推理与工具交互，结果奖励也容易诱发测试投机。</li></ul><p><strong>训练与对齐</strong></p><ul><li>预训练混合公开网页、授权、人工标注及内部数据，经过质量分类与去重。</li><li>后训练结合人类反馈、Constitutional AI 和行为特征训练，提高指令遵循与交互可靠性。</li></ul></div><div class="custom-block info"><div class="custom-block-title">Extended Thinking 与工具执行</div><p><strong>交错交互</strong></p><ul><li>同一模型支持普通回答和 Extended Thinking，按任务分配推理计算。</li><li>推理中调用工具，读取反馈后继续思考，支持并行调用和多轮操作。</li><li>提供本地文件工具时，可将任务状态写入 Memory 文件，再由后续步骤读取。</li></ul><p><strong>推理期补丁筛选</strong></p><ul><li>并行生成候选补丁，过滤破坏可见回归测试的候选，再用内部评分模型选优。</li><li>选择过程不使用隐藏测试。</li></ul></div><div class="custom-block warning"><div class="custom-block-title">Reward Hacking：训练监控与环境修正</div><p><strong>奖励漏洞</strong></p><ul><li>将测试输出硬编码或只处理测试特殊输入，可以获得表面奖励，却没有解决任务。</li></ul><p><strong>发现与修正</strong></p><ul><li>迭代行为分类器，结合无监督检查和人工审查，寻找新的投机模式。</li><li>修复可利用的环境漏洞，使指令与奖励条件一致，并持续增强奖励和评测覆盖。</li><li>训练过程中使用两组环境追踪投机，检查修改测试、绕过任务等行为。</li></ul></div><div class="custom-block important"><div class="custom-block-title">仓库修复结果</div><p><strong>SWE-bench Verified</strong></p><ul><li>完整 <code>500</code> 题，Bash + 字符串替换编辑器；主结果关闭 Extended Thinking。</li><li>Opus 4 <code>72.5</code>，Sonnet 4 <code>72.7</code>，均超过上一代。</li><li>增加并行补丁生成与选择后为 <code>79.4 / 80.2</code>，训练后仍可用搜索计算提高解决率。</li></ul></div><div class="custom-block important"><div class="custom-block-title">投机行为评测与不足</div><p><strong>困难但可解的代码任务</strong></p><ul><li>用行为分类器和独立隐藏测试分别检测补丁，避免只看可见测试是否通过。</li><li>分类器检测率：Sonnet 3.7 <code>44%</code>，Opus 4 <code>9%</code>，Sonnet 4 <code>4%</code>。</li><li>隐藏测试检测率 <code>23% → 13% / 12%</code>，改进也覆盖部分表面测试之外的错误。</li></ul><p><strong>不可解任务</strong></p><ul><li>主动加入错误测试或缺失依赖，在最小 Claude Code Harness 中观察是否如实报告失败。</li><li>Opus 4 投机率 <code>47%</code>；加入禁止投机指令后降至 <code>5%</code>。</li><li>指令能约束行为，但不可解目标带来的压力仍会诱发绕过约束，需继续完善环境验证。</li></ul></div><h2 id="_2502-claude-3-7-sonnet-hybrid-reasoning、claude-code" tabindex="-1">(2502) Claude 3.7 Sonnet (Hybrid Reasoning、Claude Code) <a class="header-anchor" href="#_2502-claude-3-7-sonnet-hybrid-reasoning、claude-code" aria-label="Permalink to &quot;(2502) Claude 3.7 Sonnet (Hybrid Reasoning、Claude Code)&quot;">​</a></h2><div class="custom-block tip"><div class="custom-block-title">Claude 3.7 Sonnet：Hybrid Reasoning 与 Claude Code</div><p><strong>来源与模式</strong></p><ul><li><a href="https://www.anthropic.com/news/claude-3-7-sonnet" target="_blank" rel="noreferrer">Claude 3.7 Sonnet and Claude Code</a>。</li><li>同一模型支持标准回答与 Extended Thinking，分别适应快答和复杂推理。</li><li>API 最大输出 <code>128K</code>，Thinking 使用其中的预算，用户可控制思考投入。</li></ul><p><strong>开发流程</strong></p><ul><li>Claude Code 在终端搜索文件、修改实现、编写和运行测试，再根据反馈修正。</li><li>推理预算控制模型计算，工具交互让模型在实际代码库中完成多步工作。</li></ul></div><div class="custom-block important"><div class="custom-block-title">公开表现与后续改进</div><p><strong>仓库求解</strong></p><ul><li>SWE-bench Verified 使用 Bash / 文件编辑，可运行 <code>489</code> 题子集。</li><li>单次求解 <code>63.7</code>，增加计算选优 <code>70.3</code>，更多候选提高可解决任务比例。</li></ul><p><strong>正常请求与工具</strong></p><ul><li>相对前代，不必要拒答减少约 <code>45%</code>，正常任务可用性改善。</li><li>官方后续计划包括提高工具可靠性、支持长时间运行命令，完善持续开发任务。</li></ul></div><h2 id="_2410-claude-3-5-sonnet更新-computer-use、屏幕到动作" tabindex="-1">(2410) Claude 3.5 Sonnet更新 (Computer Use、屏幕到动作) <a class="header-anchor" href="#_2410-claude-3-5-sonnet更新-computer-use、屏幕到动作" aria-label="Permalink to &quot;(2410) Claude 3.5 Sonnet更新 (Computer Use、屏幕到动作)&quot;">​</a></h2><div class="custom-block tip"><div class="custom-block-title">Claude 3.5 Sonnet：Computer Use</div><p><strong>来源与问题</strong></p><ul><li><a href="https://www.anthropic.com/news/3-5-models-and-computer-use" target="_blank" rel="noreferrer">模型更新</a>、<a href="https://www.anthropic.com/news/developing-computer-use" target="_blank" rel="noreferrer">Computer Use 研发</a>。</li><li>大量软件没有专用 API，需要模型理解屏幕并通过鼠标、键盘操作。</li></ul><p><strong>训练与交互</strong></p><ul><li>截图理解 → 像素坐标定位 → 点击/输入 → 新截图反馈，再判断进展或纠错。</li><li>训练包括像素定位，在计算器、文本编辑器等简单软件中学习，不开放互联网。</li><li>结合已有视觉与推理能力，迁移到未专门适配的 GUI。</li></ul></div><div class="custom-block important"><div class="custom-block-title">公开表现与不足</div><p><strong>GUI 操作</strong></p><ul><li>OSWorld <code>14.9</code>，超过当时同类对照 <code>7.7</code>，距离人类约 <code>70–75</code> 仍较远。</li><li>拖拽、缩放与连续观察仍需改进，离散截图容易漏掉短暂出现的事件。</li></ul><p><strong>代码与工具任务</strong></p><ul><li>SWE-bench Verified <code>33.4 → 49.0</code>；TAU 零售 <code>62.6 → 69.2</code>、航空 <code>36.0 → 46.0</code>。</li><li>工具能力改善覆盖代码和业务交互，Computer Use 又扩展了可操作的软件环境。</li></ul></div><h2 id="_2406-claude-3-5-sonnet-代码库交互、视觉推理" tabindex="-1">(2406) Claude 3.5 Sonnet (代码库交互、视觉推理) <a class="header-anchor" href="#_2406-claude-3-5-sonnet-代码库交互、视觉推理" aria-label="Permalink to &quot;(2406) Claude 3.5 Sonnet (代码库交互、视觉推理)&quot;">​</a></h2><div class="custom-block tip"><div class="custom-block-title">Claude 3.5 Sonnet：代码库交互与视觉理解</div><p><strong>来源与能力</strong></p><ul><li><a href="https://www.anthropic.com/news/claude-3-5-sonnet" target="_blank" rel="noreferrer">Introducing Claude 3.5 Sonnet</a>。</li><li>上下文 <code>200K</code>，面向低延迟的复杂需求处理。</li><li>根据自然语言需求读取项目、编辑代码并执行检查，支持修 Bug 和新增功能。</li><li>增强图表理解和低质量图像文字识别，辅助界面与文档相关任务。</li></ul></div><div class="custom-block important"><div class="custom-block-title">公开表现</div><p><strong>内部 Agentic Coding</strong></p><ul><li>允许读取、编辑与执行工具，以开源项目修复或功能开发是否完成评分。</li><li>Claude 3 Opus <code>38% → 3.5 Sonnet 64%</code>，反映整库理解和修改能力改善。</li></ul><p><strong>服务效率</strong></p><ul><li>官方报告运行速度约为 Claude 3 Opus 的 <code>2 倍</code>，适合多轮连续调用。</li><li>工具辅助评测覆盖实际修改与验证，比单函数补全更接近开发流程。</li></ul></div><h2 id="_2403-claude-3-opus-sonnet-haiku、视觉与长上下文" tabindex="-1">(2403) Claude 3 (Opus/Sonnet/Haiku、视觉与长上下文) <a class="header-anchor" href="#_2403-claude-3-opus-sonnet-haiku、视觉与长上下文" aria-label="Permalink to &quot;(2403) Claude 3 (Opus/Sonnet/Haiku、视觉与长上下文)&quot;">​</a></h2><div class="custom-block tip"><div class="custom-block-title">Claude 3：模型分层与多模态输入</div><p><strong>来源与分工</strong></p><ul><li><a href="https://www.anthropic.com/news/claude-3-family" target="_blank" rel="noreferrer">Introducing the next generation of Claude</a>。</li><li>Opus 面向复杂推理，Sonnet 兼顾服务吞吐，Haiku 面向实时响应。</li><li>首发上下文 <code>200K</code>，直接处理照片、图表、流程图和技术文档。</li></ul><p><strong>对齐与交互</strong></p><ul><li>继续改进 Constitutional AI，减少正常请求上的过度拒答。</li><li>发布时提出扩展 Tool Use 与交互式代码执行，完善 Agent 能力。</li></ul></div><div class="custom-block important"><div class="custom-block-title">长文与事实性表现</div><p><strong>长文检索</strong></p><ul><li>NIAH 从 <code>30</code> 组针与问题中随机选择，在长文不同位置插入目标信息。</li><li>Opus 准确率超过 <code>99%</code>，验证长窗口中的指定信息检索能力。</li></ul><p><strong>事实问答</strong></p><ul><li>内部困难问答分别统计正确、错误与明确表示不确定的回答。</li><li>相对 Claude 2.1，正确率约提高 <code>2 倍</code>，同时减少错误答案。</li></ul></div><h2 id="_2212-constitutional-ai-自我修订与-ai-偏好" tabindex="-1">(2212) Constitutional AI (自我修订与 AI 偏好) <a class="header-anchor" href="#_2212-constitutional-ai-自我修订与-ai-偏好" aria-label="Permalink to &quot;(2212) Constitutional AI (自我修订与 AI 偏好)&quot;">​</a></h2><p><strong>🌺 论文摘要</strong></p><div class="custom-block danger"><div class="custom-block-title">Constitutional AI 摘要</div><p><strong>参考链接</strong></p><ul><li><a href="https://arxiv.org/abs/2212.08073" target="_blank" rel="noreferrer">paper</a>。</li></ul><p><strong>问题背景</strong></p><ul><li>人工逐条判断有害回答成本高；单纯奖励拒答容易形成回避式回答。</li></ul><p><strong>核心方法</strong></p><ul><li><strong>SL-CAI</strong>：按原则批评与修订回答，生成 SFT 数据。</li><li><strong>RL-CAI</strong>：AI 偏好 → Preference Model → RLAIF；结合 CoT、多原则与软标签校准。</li></ul><p><strong>模型效果</strong></p><ul><li><code>52B</code> 模型经过 RLAIF 后，无害性提高，同时保留接近原模型的帮助性。</li></ul><p><strong>重要结论</strong></p><ul><li>少量原则能够组织大规模 AI 反馈；反馈概率与评测准则直接影响策略行为。</li></ul><p><strong>核心贡献</strong></p><ul><li>建立原则驱动的 SFT + RLAIF 流程，将无害性监督从逐条人工标注扩展为 AI 反馈。</li></ul><p><strong>未来方向</strong></p><ul><li>扩展原则覆盖和 AI 监督范围，减少对大量逐条人工比较的依赖。</li><li>改善偏好校准与奖励过度优化，兼顾无害性、帮助性和有效回应。</li></ul></div><h3 id="问题背景" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景" aria-label="Permalink to &quot;问题背景&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">无害性监督与有效回答</div><ul><li>逐条人工比较有害回答成本高，难以持续扩展监督。</li><li>只奖励拒答会造成回避式回答，需要在无害性与帮助性之间保留有效回应。</li><li>论文用少量原则组织自我修订与 AI 偏好，扩展人工反馈的覆盖。</li></ul></div><h3 id="核心方法" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法" aria-label="Permalink to &quot;核心方法&quot;">​</a></h3><h4 id="原则驱动的监督微调" tabindex="-1">原则驱动的监督微调 <a class="header-anchor" href="#原则驱动的监督微调" aria-label="Permalink to &quot;原则驱动的监督微调&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">原则驱动的回答修订</div><p><strong>原始回答</strong></p><ul><li>Helpful RLHF 模型回答 Red-team Prompt，得到可能包含有害内容的回答。</li></ul><p><strong>Critique → Revision</strong></p><ul><li>从 <code>16</code> 条原则中抽样一条，让模型指出回答违反原则的位置，再生成修订答案。</li><li>使用 Few-shot 示例区分批评与回答；每个 Prompt 连续做 <code>4</code> 轮修订。</li></ul><p><strong>训练样本</strong></p><ul><li>收集各轮的「原始 Prompt + 修订答案」，不把整段批评过程作为最终回答。</li><li>混合 Helpful RLHF 模型生成的普通帮助性回答，保留正常任务能力。</li><li>从预训练模型做 SFT，得到 SL-CAI。</li></ul></div><h4 id="ai-偏好与-rlaif" tabindex="-1">AI 偏好与 RLAIF <a class="header-anchor" href="#ai-偏好与-rlaif" aria-label="Permalink to &quot;AI 偏好与 RLAIF&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">候选比较与 Preference Model</div><p><strong>AI 偏好构建</strong></p><ul><li>SL-CAI 对同一 Prompt 生成两个候选回答。</li><li>Feedback LM 根据抽样原则选择 A/B，用归一化选择概率得到软偏好标签。</li><li>混合 AI 的无害性偏好与人类的帮助性偏好，训练 Preference Model。</li></ul><p><strong>策略更新</strong></p><ul><li>以 SL-CAI 为初始策略，使用 Preference Model 的评分进行 RL。</li><li>AI 主要替代无害性比较标注；帮助性训练仍保留人类反馈。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">CoT 反馈与软标签校准</div><p><strong>CoT Judge</strong></p><ul><li>Feedback LM 先分析两个回答，再给出选择，提高复杂比较的判断质量。</li></ul><p><strong>概率截断</strong></p><ul><li>CoT 容易产生接近 <code>0 / 1</code> 的极端偏好，导致 PM 对差异过度确信。</li><li>将选择概率截断到 <code>0.4–0.6</code>，保留偏好方向，降低偏好标签的过度确信，减少极端奖励信号。</li></ul><p><strong>多原则组合</strong></p><ul><li>不同样本使用不同原则，提高反馈多样性，减少单一原则产生的固定措辞。</li></ul></div><figure style="margin:24px 0;"><img src="https://arxiv.org/html/2212.08073v1/CAI-Overview.png" alt="Constitutional AI 的两阶段流程：先按原则批评并修订回答做 SFT，再生成 AI 偏好标签，训练偏好模型与 RL 策略。" loading="lazy" style="display:block;margin:12px auto;background:#fff;" width="100%"><figcaption style="font-size:0.9em;line-height:1.6;color:var(--vp-c-text-2);"><strong>原文图 1：</strong>Constitutional AI 的两阶段流程：先按原则批评并修订回答做 SFT，再生成 AI 偏好标签，训练偏好模型与 RL 策略。 <a href="https://arxiv.org/html/2212.08073#S1.F1" target="_blank" rel="noreferrer">来源</a></figcaption></figure><h3 id="实验设置-constitutional-ai" tabindex="-1">实验设置(Constitutional AI) <a class="header-anchor" href="#实验设置-constitutional-ai" aria-label="Permalink to &quot;实验设置(Constitutional AI)&quot;">​</a></h3><div class="custom-block tip"><div class="custom-block-title">实验设置</div><p><strong>模型与数据</strong></p><ul><li>主实验 <code>52B</code>；另比较不同规模的 AI 判断与自我修订能力。</li><li>Red-team Prompt 约 <code>183K</code>：人工约 <code>42.5K</code>，模型生成约 <code>140.3K</code>。</li><li>帮助性 Prompt 约 <code>135K</code>，每条由 Helpful RLHF 模型生成两个回答。</li></ul><p><strong>SL 与 PM 训练</strong></p><ul><li>每条 Red-team Prompt 做 <code>4</code> 轮修订，采样温度 <code>1</code>。</li><li>SL：<code>1 epoch</code>，Batch Size <code>1024</code>，固定学习率为预训练学习率的 <code>0.5</code> 倍。</li><li>PM：约 <code>135K</code> 人类帮助性比较 + <code>183K</code> AI 无害性比较。</li></ul><p><strong>评测与消融</strong></p><ul><li>人工分别比较帮助性与无害性，并使用 <code>0–4</code> 绝对有害程度评分。</li><li>对照直接修订 / 先批评再修订、修订轮数、CoT 判断、软标签 / 硬标签 / 截断标签。</li></ul></div><h3 id="关键结果-constitutional-ai" tabindex="-1">关键结果(Constitutional AI) <a class="header-anchor" href="#关键结果-constitutional-ai" aria-label="Permalink to &quot;关键结果(Constitutional AI)&quot;">​</a></h3><div class="custom-block important"><div class="custom-block-title">关键结果</div><p><strong>帮助性与无害性</strong></p><ul><li>RL-CAI 在人类比较中比 SL-CAI 更无害，帮助性仅有较小变化。</li><li>评测同时奖励有效回应，减少把回避问题误判为更安全的情况。</li></ul><p><strong>自我修订</strong></p><ul><li>小模型从显式 Critique 中获益更明显；<code>52B</code> 模型直接修订也能达到接近效果。</li><li>增加修订轮数通常提高无害性，但可能损失帮助性，需要混合普通任务数据。</li></ul><p><strong>反馈与奖励优化</strong></p><ul><li>非 CoT 的软标签优于硬标签；CoT 反馈结合 <code>0.4–0.6</code> 截断表现更好。</li><li>长时间优化单一奖励可能产生指责性或模板化回答，多原则和概率校准可缓解这一问题。</li></ul></div><figure style="margin:24px 0;"><img src="https://arxiv.org/html/2212.08073v1/Constitutional.png" alt="人类比较得到的帮助性—无害性曲线。RL-CAI 在保持帮助性的同时改善无害性，观察两项目标的共同变化。" loading="lazy" style="display:block;margin:12px auto;background:#fff;" width="100%"><figcaption style="font-size:0.9em;line-height:1.6;color:var(--vp-c-text-2);"><strong>原文图 2：</strong>人类比较得到的帮助性—无害性曲线。RL-CAI 在保持帮助性的同时改善无害性，观察两项目标的共同变化。 <a href="https://arxiv.org/html/2212.08073#S1.F2" target="_blank" rel="noreferrer">来源</a></figcaption></figure><h3 id="未来方向" tabindex="-1">未来方向 <a class="header-anchor" href="#未来方向" aria-label="Permalink to &quot;未来方向&quot;">​</a></h3><div class="custom-block info"><div class="custom-block-title">未来方向</div><p><strong>笔记讨论</strong></p><ul><li>扩展原则覆盖和 AI 监督范围，减少对大量逐条人工比较的依赖。</li><li>改善偏好校准与奖励过度优化，兼顾无害性、帮助性和有效回应。</li></ul></div><h2 id="_2512-anthropic-interviewer-1250人访谈、用户研究" tabindex="-1">(2512) Anthropic Interviewer (1250人访谈、用户研究) <a class="header-anchor" href="#_2512-anthropic-interviewer-1250人访谈、用户研究" aria-label="Permalink to &quot;(2512) Anthropic Interviewer (1250人访谈、用户研究)&quot;">​</a></h2><div class="custom-block tip"><div class="custom-block-title">Anthropic Interviewer：自适应访谈流程</div><p><strong>来源与定位</strong></p><ul><li><a href="https://www.anthropic.com/research/anthropic-interviewer" target="_blank" rel="noreferrer">官方研究</a>、<a href="https://huggingface.co/datasets/Anthropic/AnthropicInterviewer" target="_blank" rel="noreferrer">访谈数据</a>。</li><li>聊天日志难以看到 AI 产物如何被采用，也难解释用户需求和顾虑。</li><li>本项基于 Claude 与 Prompt 构建用户研究流程，不提出新模型训练方法。</li></ul><p><strong>研究流程</strong></p><ul><li>研究者提出目标，模型生成 Rubric、问题与流程，经人工修订后用于访谈。</li><li>访谈围绕共同研究问题展开，并根据个体回答自适应追问。</li><li>人与 AI 结合原文、示例和访谈计划分析，再聚类主题、统计出现频率。</li></ul></div><div class="custom-block note"><div class="custom-block-title">样本与分析设置</div><ul><li>共 <code>1250</code> 人：一般职业 <code>1000</code> 人，科学与创意工作者各 <code>125</code> 人。</li><li>每次访谈约 <code>10–15 分钟</code>，同时收集职业和使用情况问卷。</li><li>定性主题与问卷统计结合；众包平台样本，不是总体随机抽样调查。</li></ul></div><div class="custom-block important"><div class="custom-block-title">研究发现</div><p><strong>使用体验</strong></p><ul><li>一般职业样本中，<code>86%</code> 自述节省时间，<code>65%</code> 满意工作中的 AI 使用。</li><li>用户倾向保留体现专业身份的工作，把日常重复任务交给 AI。</li></ul><p><strong>与行为日志互补</strong></p><ul><li>访谈更多描述协作式使用，聊天记录呈现更多自动化行为。</li><li>需要结合产物采用方式和样本差异解释，自述比例不等于直接测得的效率增益。</li><li>后续研究扩展职业、地区和长期追踪，将访谈与实际使用记录结合。</li></ul></div>',58)]))}const h=i(a,[["render",s]]);export{g as __pageData,h as default};
